-- ============================================================
-- Migration: repoint third-party product images (Shopify CDN, Wix) at Cloudflare R2
--
-- Product photos for three vendors were hot-linked from cdn.shopify.com and static.wixstatic.com, so they
-- disappear if a vendor changes or closes their store. 314 distinct images were copied to R2 under
-- products/mirrored/ (each verified byte-identical on media.lifestylemedicinegateway.com). Images with a side
-- over 1600px were resized and recompressed first, because the site serves media.* URLs as-is with no
-- resizing proxy (Wix and Shopify images went through one before). 315 old URL strings map to those files
-- (some descriptions write the same image as a protocol-relative //cdn.shopify.com/... URL).
--
-- Updates, from the temp table below:
--   * products.image_url          exact match
--   * products.images (text[])    each array element
--   * products.content            every occurrence inside the description HTML
--
-- Left alone on purpose: 2 Shopify images that already return 404 at the source (Angel-cream-foundation_medium.jpg
-- and Goddessey-sample-web_100x100.jpg, in one vendor's descriptions), so there is nothing to copy.
--
-- Applied 2026-11-02; no need to run it again. (A second run fails in the SQL Editor with "relation _img_map does not
-- exist", because the editor does not keep temp tables between statements. Nothing is harmed by that.)
-- Run in the SQL Editor (whole file, nothing selected). Check afterwards (expect 0, 0, 6):
--   select count(*) from products where image_url ~ 'cdn\.shopify\.com|wixstatic\.com';
--   select count(*) from products, unnest(images) u where u ~ 'cdn\.shopify\.com|wixstatic\.com';
--   select count(*) from products where content ~ 'cdn\.shopify\.com|wixstatic\.com';   -- the 6 products that hold the 2 dead images
-- ============================================================

BEGIN;

CREATE TEMP TABLE _img_map (old_url text PRIMARY KEY, new_url text NOT NULL) ON COMMIT DROP;


UPDATE public.products p
SET image_url = m.new_url
FROM _img_map m
WHERE p.image_url = m.old_url;

UPDATE public.products p
SET images = (
  SELECT array_agg(COALESCE(m.new_url, t.u) ORDER BY t.ord)
  FROM unnest(p.images) WITH ORDINALITY AS t(u, ord)
  LEFT JOIN _img_map m ON m.old_url = t.u
)
WHERE p.images && (SELECT array_agg(old_url) FROM _img_map);

-- Longest URL first: the https://... form of an image is replaced before its //... form, so the shorter string
-- can never match inside one that is still waiting (and leave "https:https://..." behind).
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT old_url, new_url FROM _img_map ORDER BY length(old_url) DESC LOOP
    UPDATE public.products
    SET content = replace(content, r.old_url, r.new_url)
    WHERE position(r.old_url IN content) > 0;
  END LOOP;
END
$$;

COMMIT;
